CREATE OR REPLACE FUNCTION rakeezx.guard_live_student_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_student text; v_students text[] := '{}'; v_section text;
begin
  -- Match force_owner BEFORE taking a lock or checking parent identity. A
  -- caller-supplied owner must not select another account's safety boundary.
  if tg_op='INSERT' and auth.uid() is not null then new.owner_id:=auth.uid(); end if;
  -- Statement gate / RPC entry already holds the owner lock before row locks.
  if tg_table_name='students' and tg_op='UPDATE' then
    if old.deleted_at is not null and new.deleted_at is null then
      raise exception using errcode='23503',message='STUDENT_TOMBSTONED';
    end if;
    if old.deleted_at is null and new.deleted_at is not null and
      coalesce(current_setting('rakeezx.pristine_student_delete',true),'')<>'on' then
      raise exception using errcode='22023',message='USE_PRISTINE_STUDENT_COMMAND';
    end if;
  end if;
  if tg_table_name in ('enrollments','scores','attendance','logs','notes') then
    if new.deleted_at is not null then return new; end if;
    v_students := array[new.student_id];
  elsif tg_table_name='session_roster_snapshots' then
    -- Snapshot reads and immutable historical members are untouched.
    if tg_op<>'INSERT' or new.deleted_at is not null then return new; end if;
    select coalesce(array_agg(m->>'studentId'),'{}') into v_students
      from pg_catalog.jsonb_array_elements(new.members) m;
  end if;
  foreach v_student in array v_students loop
    if not exists(select 1 from rakeezx.students where owner_id=new.owner_id and id=v_student and deleted_at is null) then
      raise exception using errcode='23503',message='STUDENT_TOMBSTONED',detail='Active child evidence requires a live student';
    end if;
  end loop;
  if tg_table_name in ('logs','attendance') then
  if tg_op='INSERT' and new.deleted_at is null then
    select section_id into v_section from rakeezx.teachings where owner_id=new.owner_id and id=new.teaching_id;
    if exists(select 1 from rakeezx.enrollments where owner_id=new.owner_id and student_id=new.student_id
      and section_id=v_section and status<>'active' and end_date is not null and new.date>=end_date and deleted_at is null)
      and not exists(select 1 from rakeezx.enrollments where owner_id=new.owner_id and student_id=new.student_id
        and section_id=v_section and status='active' and deleted_at is null) then
      raise exception using errcode='23503',message='ENROLLMENT_ENDED';
    end if;
  end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.force_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.owner_id := auth.uid();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.sync_v2_stamp_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_field_map jsonb := rakeezx.sync_v2_field_map(tg_table_name);
  v_field text;
  v_group text;
  v_next_revision bigint;
  v_revisions jsonb;
  v_changed boolean := false;
begin
  if tg_op = 'INSERT' then
    new.revision := 1;
    new.field_revisions := rakeezx.sync_v2_initial_field_revisions(tg_table_name, 1);
    if new.deleted_at is not null then
      new.field_revisions := pg_catalog.jsonb_set(
        new.field_revisions, array['__deleted__'], '1'::jsonb, true
      );
    end if;
    return new;
  end if;

  -- A tombstone is immutable through every generic write path. Returning NULL
  -- skips the row update entirely, including metadata churn. A future restore
  -- requires a separate validated command rather than an UPDATE bypass.
  if old.deleted_at is not null then
    return null;
  end if;

  v_next_revision := old.revision + 1;
  v_revisions := coalesce(old.field_revisions, '{}'::jsonb);
  for v_field, v_group in
    select entry.key, entry.value #>> '{}'
    from pg_catalog.jsonb_each(v_field_map) as entry
  loop
    if (pg_catalog.to_jsonb(new) -> v_field) is distinct from (pg_catalog.to_jsonb(old) -> v_field) then
      v_changed := true;
      v_revisions := pg_catalog.jsonb_set(v_revisions, array[v_group], pg_catalog.to_jsonb(v_next_revision), true);
    end if;
  end loop;
  if new.deleted_at is distinct from old.deleted_at then
    v_changed := true;
    v_revisions := pg_catalog.jsonb_set(v_revisions, array['__deleted__'], pg_catalog.to_jsonb(v_next_revision), true);
  end if;

  -- The server revision describes domain mutations, not device/timestamp
  -- bookkeeping. Preserve the current revision for an identical/no-op patch.
  if not v_changed then
    new.revision := old.revision;
    new.field_revisions := old.field_revisions;
    return new;
  end if;

  new.revision := v_next_revision;
  new.field_revisions := v_revisions;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := pg_catalog.now();
  if new.owner_id is null then
    new.owner_id := auth.uid();
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.guard_archived_section_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_section text; v_old_section text; v_status text;
begin
  if pg_catalog.current_setting('rakeezx.section_lifecycle_delete', true) = 'on' then return new; end if;
  v_section := rakeezx.section_for_operational_row(tg_table_name, to_jsonb(new));
  if tg_op = 'UPDATE' then v_old_section := rakeezx.section_for_operational_row(tg_table_name, to_jsonb(old)); end if;
  for v_section in select distinct candidate from unnest(array[v_section,v_old_section]) candidate where candidate is not null order by candidate loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.owner_id::text||':section-lifecycle:'||v_section,0));
    select status into v_status from rakeezx.sections where owner_id=new.owner_id and id=v_section and deleted_at is null;
    if v_status = 'archived' then
      raise exception using errcode='22023', message='Archived section is read-only';
    end if;
  end loop;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.n77_guard_live_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row jsonb := pg_catalog.to_jsonb(new);
  v_owner uuid := new.owner_id;
  v_section text := v_row->>'section_id';
  v_teaching text := v_row->>'teaching_id';
  v_item text := v_row->>'item_id';
  v_subitem text := v_row->>'subitem_id';
  v_session text := v_row->>'session_id';
  v_student text := v_row->>'student_id';
  v_parent rakeezx.sections%rowtype;
begin
  if v_row->>'deleted_at' is not null then return new; end if;
  if v_student is not null and not exists (
    select 1 from rakeezx.students where owner_id=v_owner and id=v_student and deleted_at is null
  ) then raise exception using errcode='22023',message='N77 student is unavailable'; end if;
  if v_subitem is not null then
    select si.item_id into v_item from rakeezx.score_subitems si
      where si.owner_id=v_owner and si.id=v_subitem and si.deleted_at is null;
    if v_item is null then raise exception using errcode='22023',message='N77 subitem is unavailable'; end if;
  end if;
  if v_item is not null then
    select i.teaching_id into v_teaching from rakeezx.items i
      where i.owner_id=v_owner and i.id=v_item and i.deleted_at is null;
    if v_teaching is null then raise exception using errcode='22023',message='N77 item is unavailable'; end if;
  end if;
  if v_session is not null then
    if v_teaching is null then
      select s.teaching_id into v_teaching from rakeezx.sessions s
        where s.owner_id=v_owner and s.id=v_session and s.deleted_at is null;
      if v_teaching is null then raise exception using errcode='22023',message='N77 session is unavailable'; end if;
    elsif not exists (select 1 from rakeezx.sessions s where s.owner_id=v_owner and s.id=v_session
      and s.teaching_id=v_teaching and s.deleted_at is null) then
      raise exception using errcode='22023',message='N77 session scope mismatch';
    end if;
  end if;
  if v_teaching is not null then
    select t.section_id into v_section from rakeezx.teachings t
      where t.owner_id=v_owner and t.id=v_teaching and t.deleted_at is null;
    if v_section is null then raise exception using errcode='22023',message='N77 teaching is unavailable'; end if;
  end if;
  if v_section is not null then
    select * into v_parent from rakeezx.sections
      where owner_id=v_owner and id=v_section for share;
    if not found or v_parent.deleted_at is not null then
      raise exception using errcode='22023',message='N77 section is unavailable';
    end if;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.record_owner_sync_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid; v_revision bigint;
begin
  if TG_OP='UPDATE' and NEW is not distinct from OLD then return NEW; end if;
  if TG_OP='DELETE' then v_owner:=OLD.owner_id; else v_owner:=NEW.owner_id; end if;
  if TG_OP='UPDATE' and NEW.owner_id is distinct from OLD.owner_id then
    raise exception 'Owner identity is immutable' using errcode='42501';
  end if;
  if auth.uid() is not null and auth.uid()<>v_owner then
    raise exception 'Owner mismatch' using errcode='42501';
  end if;
  -- Account deletion cascades must not recreate its marker.
  if not exists(select 1 from auth.users where id=v_owner) then
    if TG_OP='DELETE' then return OLD; else return NEW; end if;
  end if;
  insert into rakeezx.owner_sync_changes(owner_id,revision,updated_at)
    values(v_owner,1,clock_timestamp())
    on conflict(owner_id) do update set revision=owner_sync_changes.revision+1,
      updated_at=clock_timestamp() returning revision into v_revision;
  perform realtime.send(jsonb_build_object('revision',v_revision::text),
    'invalidate','rakeezx-owner:'||v_owner::text,true);
  if TG_OP='DELETE' then return OLD; else return NEW; end if;
end;
$function$

