CREATE OR REPLACE FUNCTION rakeezx.begin_account_provisioning()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid := auth.uid(); v_profile rakeezx.profile%rowtype;
begin
  if v_owner is null then raise exception using errcode='42501', message='Authentication required'; end if;
  select * into v_profile from rakeezx.profile where owner_id=v_owner for update;
  if v_profile.owner_id is null or v_profile.provisioning_state is null then
    raise exception using errcode='42501', message='Account is not a fresh provisioning candidate';
  end if;
  if v_profile.profile_status <> 'READY' or v_profile.teacher_name = '' or
      v_profile.phone !~ '^05[0-9]{8}$' or
      not exists(select 1 from rakeezx.account_access_grants
        where owner_id=v_owner and grant_type='beta_full' and status='active' and
          (expires_at is null or expires_at > now())) then
    raise exception using errcode='42501', message='Profile or Beta access is not ready';
  end if;
  if v_profile.provisioning_state='PROVISIONING_REQUIRED' then
    perform pg_catalog.set_config('rakeezx.account_provisioning_control','allow',true);
    update rakeezx.profile set provisioning_state='PROVISIONING', provisioning_started_at=now()
      where owner_id=v_owner;
  elsif v_profile.provisioning_state not in ('PROVISIONING','READY') then
    raise exception using errcode='42501', message='Profile completion is required';
  end if;
  return rakeezx.account_contract();
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.commit_enrollment_transfer(p_source jsonb, p_destination jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_source_id text := p_source ->> 'id';
  v_destination_id text := p_destination ->> 'id';
  v_student_id text := p_source ->> 'student_id';
  v_source_section_id text := p_source ->> 'section_id';
  v_destination_section_id text := p_destination ->> 'section_id';
  v_source rakeezx.enrollments%rowtype;
  v_destination rakeezx.enrollments%rowtype;
  v_source_section rakeezx.sections%rowtype;
  v_destination_section rakeezx.sections%rowtype;
  v_source_found boolean := false;
  v_destination_found boolean := false;
  v_source_stamp bigint := nullif(p_source ->> 'client_updated_at', '')::bigint;
  v_destination_stamp bigint := nullif(p_destination ->> 'client_updated_at', '')::bigint;
  v_destination_roll integer := nullif(p_destination ->> 'roll_no', '')::integer;
begin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||':student-lifecycle-safety',0));
  if v_owner is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  if p_source is null or p_destination is null or
      coalesce(v_source_id, '') = '' or coalesce(v_destination_id, '') = '' or v_source_id = v_destination_id or
      v_student_id is null or v_student_id = '' or
      p_destination ->> 'student_id' is distinct from v_student_id or
      p_source ->> 'status' is distinct from 'transferred' or
      p_destination ->> 'status' is distinct from 'active' or
      coalesce(v_source_section_id, '') = '' or coalesce(v_destination_section_id, '') = '' or
      v_source_section_id = v_destination_section_id or
      v_source_stamp is null or v_destination_stamp is null or
      v_destination_roll is null or v_destination_roll not between 1 and 999 then
    raise exception using errcode = '22023', message = 'Invalid enrollment transfer payload';
  end if;

  -- Serializes competing transfer requests for one student without imposing a
  -- new global active-membership index on uninspected existing production data.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':' || v_student_id, 0));
  -- The source may be historical, but it must still be a section owned by this
  -- caller.  The destination must be an active owned section before either
  -- enrollment row can be changed.
  select * into v_source_section from rakeezx.sections
    where owner_id = v_owner and id = v_source_section_id
    for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'Source section is not owned by current user';
  end if;
  select * into v_destination_section from rakeezx.sections
    where owner_id = v_owner and id = v_destination_section_id
    for update;
  if not found or v_destination_section.deleted_at is not null then
    raise exception using errcode = 'P0001', message = 'Destination section is not active for current user';
  end if;

  perform 1 from rakeezx.enrollments
    where owner_id = v_owner and student_id = v_student_id
    for update;

  select * into v_source from rakeezx.enrollments
    where owner_id = v_owner and id = v_source_id
    for update;
  v_source_found := found;
  select * into v_destination from rakeezx.enrollments
    where owner_id = v_owner and id = v_destination_id
    for update;
  v_destination_found := found;

  -- IDs are technical identities, not authority to rewrite any owned row.
  -- Existing rows must match every immutable transfer identity in the receipt.
  if (v_source_found and (
        v_source.owner_id is distinct from v_owner or
        v_source.id is distinct from v_source_id or
        v_source.student_id is distinct from v_student_id or
        v_source.section_id is distinct from v_source_section_id
      )) or
      (v_destination_found and (
        v_destination.owner_id is distinct from v_owner or
        v_destination.id is distinct from v_destination_id or
        v_destination.student_id is distinct from v_student_id or
        v_destination.section_id is distinct from v_destination_section_id
      )) then
    raise exception using errcode = 'P0001', message = 'Enrollment identity does not match transfer payload';
  end if;

  if (v_source_found and v_source.deleted_at is not null) or
      (v_destination_found and v_destination.deleted_at is not null) then
    raise exception using errcode = 'P0001', message = 'Enrollment tombstone cannot be reactivated';
  end if;
  if (v_source_found and coalesce(v_source.client_updated_at, 0) > v_source_stamp) or
      (v_destination_found and coalesce(v_destination.client_updated_at, 0) > v_destination_stamp) then
    raise exception using errcode = 'P0001', message = 'Enrollment transfer is stale';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and student_id = v_student_id and deleted_at is null and status = 'active'
        and id not in (v_source_id, v_destination_id)
  ) then
    raise exception using errcode = 'P0001', message = 'Another active enrollment already exists';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and student_id = v_student_id
        and section_id = p_destination ->> 'section_id' and id <> v_destination_id
  ) then
    raise exception using errcode = 'P0001', message = 'Destination enrollment identity conflict';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and section_id = p_destination ->> 'section_id'
        and status = 'active' and deleted_at is null and roll_no = v_destination_roll
        and id not in (v_source_id, v_destination_id)
  ) then
    raise exception using errcode = '23505', message = 'Destination roll number is already active';
  end if;

  if v_source_found then
    update rakeezx.enrollments
      set status = 'transferred',
          end_date = nullif(p_source ->> 'end_date', '')::date,
          transfer_note = coalesce(p_source ->> 'transfer_note', ''),
          client_updated_at = v_source_stamp,
          device_id = p_source ->> 'device_id'
      where owner_id = v_owner and id = v_source_id
      returning * into v_source;
  else
    insert into rakeezx.enrollments (
      id, student_id, section_id, roll_no, start_date, end_date, status,
      transfer_note, client_updated_at, device_id
    ) values (
      v_source_id, v_student_id, p_source ->> 'section_id',
      nullif(p_source ->> 'roll_no', '')::integer,
      nullif(p_source ->> 'start_date', '')::date,
      nullif(p_source ->> 'end_date', '')::date,
      'transferred', coalesce(p_source ->> 'transfer_note', ''),
      v_source_stamp, p_source ->> 'device_id'
    ) returning * into v_source;
  end if;

  if v_destination_found then
    update rakeezx.enrollments
      set roll_no = v_destination_roll,
          start_date = nullif(p_destination ->> 'start_date', '')::date,
          end_date = null,
          status = 'active',
          client_updated_at = v_destination_stamp,
          device_id = p_destination ->> 'device_id'
      where owner_id = v_owner and id = v_destination_id
      returning * into v_destination;
  else
    insert into rakeezx.enrollments (
      id, student_id, section_id, roll_no, start_date, end_date, status,
      transfer_note, client_updated_at, device_id
    ) values (
      v_destination_id, v_student_id, p_destination ->> 'section_id',
      v_destination_roll, nullif(p_destination ->> 'start_date', '')::date,
      null, 'active', coalesce(p_destination ->> 'transfer_note', ''),
      v_destination_stamp, p_destination ->> 'device_id'
    ) returning * into v_destination;
  end if;

  return pg_catalog.jsonb_build_object(
    'source', pg_catalog.to_jsonb(v_source),
    'destination', pg_catalog.to_jsonb(v_destination)
  );
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.commit_enrollment_transfer_and_renumber(p_source jsonb, p_destination jsonb, p_source_roster jsonb, p_destination_roster jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_source_id text := p_source ->> 'id';
  v_destination_id text := p_destination ->> 'id';
  v_student_id text := p_source ->> 'student_id';
  v_source_section_id text := p_source ->> 'section_id';
  v_destination_section_id text := p_destination ->> 'section_id';
  v_source_stamp bigint := nullif(p_source ->> 'client_updated_at', '')::bigint;
  v_destination_stamp bigint := nullif(p_destination ->> 'client_updated_at', '')::bigint;
  v_destination_roll integer := nullif(p_destination ->> 'roll_no', '')::integer;
  v_source rakeezx.enrollments%rowtype;
  v_destination rakeezx.enrollments%rowtype;
  v_source_found boolean := false;
  v_destination_found boolean := false;
  v_source_plan_count integer;
  v_destination_plan_count integer;
  v_source_active_count integer;
  v_destination_active_count integer;
begin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||':student-lifecycle-safety',0));
  if v_owner is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  if pg_catalog.jsonb_typeof(p_source) <> 'object' or pg_catalog.jsonb_typeof(p_destination) <> 'object' or
      pg_catalog.jsonb_typeof(p_source_roster) <> 'array' or pg_catalog.jsonb_typeof(p_destination_roster) <> 'array' or
      coalesce(v_source_id, '') = '' or coalesce(v_destination_id, '') = '' or v_source_id = v_destination_id or
      coalesce(v_student_id, '') = '' or p_destination ->> 'student_id' is distinct from v_student_id or
      p_source ->> 'status' is distinct from 'transferred' or p_destination ->> 'status' is distinct from 'active' or
      coalesce(v_source_section_id, '') = '' or coalesce(v_destination_section_id, '') = '' or
      v_source_section_id = v_destination_section_id or v_source_stamp is null or v_destination_stamp is null or
      v_destination_roll is null or v_destination_roll not between 1 and 999 then
    raise exception using errcode = '22023', message = 'Invalid transfer-and-renumber payload';
  end if;

  -- Reject malformed plans before any membership row is changed.  NULL is not
  -- allowed as a final number; it is only an internal, transaction-local step.
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(p_source_roster) as entry(value)
      where pg_catalog.jsonb_typeof(entry.value) is distinct from 'object'
        or coalesce(entry.value ->> 'id', '') = ''
        or pg_catalog.jsonb_typeof(entry.value -> 'roll_no') is distinct from 'number'
        or not ((entry.value ->> 'roll_no') ~ '^[1-9][0-9]{0,2}$')
        or pg_catalog.jsonb_typeof(entry.value -> 'client_updated_at') is distinct from 'number'
  ) or exists (
    select 1 from pg_catalog.jsonb_array_elements(p_destination_roster) as entry(value)
      where pg_catalog.jsonb_typeof(entry.value) is distinct from 'object'
        or coalesce(entry.value ->> 'id', '') = ''
        or pg_catalog.jsonb_typeof(entry.value -> 'roll_no') is distinct from 'number'
        or not ((entry.value ->> 'roll_no') ~ '^[1-9][0-9]{0,2}$')
        or pg_catalog.jsonb_typeof(entry.value -> 'client_updated_at') is distinct from 'number'
  ) then
    raise exception using errcode = '22023', message = 'Invalid final enrollment roster';
  end if;

  -- Serialize one student first, then the two sections in a deterministic
  -- order.  This prevents concurrent transfers/renumbers from interleaving.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':' || v_student_id, 0));
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':section:' || least(v_source_section_id, v_destination_section_id), 0));
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':section:' || greatest(v_source_section_id, v_destination_section_id), 0));

  perform 1 from rakeezx.sections
    where owner_id = v_owner and id in (v_source_section_id, v_destination_section_id)
    order by id for update;
  if (select count(*) from rakeezx.sections
      where owner_id = v_owner and id in (v_source_section_id, v_destination_section_id)) <> 2 then
    raise exception using errcode = 'P0001', message = 'Transfer section is not owned by current user';
  end if;
  if exists (
    select 1 from rakeezx.sections
      where owner_id = v_owner and id = v_destination_section_id and deleted_at is not null
  ) then
    raise exception using errcode = 'P0001', message = 'Destination section is not active for current user';
  end if;

  -- Lock every membership whose state or final number this operation uses.
  perform 1 from rakeezx.enrollments
    where owner_id = v_owner and (student_id = v_student_id or section_id in (v_source_section_id, v_destination_section_id))
    order by section_id, id for update;

  select * into v_source from rakeezx.enrollments
    where owner_id = v_owner and id = v_source_id;
  v_source_found := found;
  select * into v_destination from rakeezx.enrollments
    where owner_id = v_owner and id = v_destination_id;
  v_destination_found := found;

  if (v_source_found and (
        v_source.student_id is distinct from v_student_id or v_source.section_id is distinct from v_source_section_id
      )) or (v_destination_found and (
        v_destination.student_id is distinct from v_student_id or v_destination.section_id is distinct from v_destination_section_id
      )) then
    raise exception using errcode = 'P0001', message = 'Enrollment identity does not match transfer payload';
  end if;
  if (v_source_found and v_source.deleted_at is not null) or (v_destination_found and v_destination.deleted_at is not null) then
    raise exception using errcode = 'P0001', message = 'Enrollment tombstone cannot be reactivated';
  end if;
  if (v_source_found and coalesce(v_source.client_updated_at, 0) > v_source_stamp) or
      (v_destination_found and coalesce(v_destination.client_updated_at, 0) > v_destination_stamp) then
    raise exception using errcode = 'P0001', message = 'Enrollment transfer is stale';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and student_id = v_student_id and deleted_at is null and status = 'active'
        and id not in (v_source_id, v_destination_id)
  ) then
    raise exception using errcode = 'P0001', message = 'Another active enrollment already exists';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and student_id = v_student_id and section_id = v_destination_section_id
        and id <> v_destination_id
  ) then
    raise exception using errcode = 'P0001', message = 'Destination enrollment identity conflict';
  end if;

  -- First commit membership with no active destination roll.  The final plans
  -- below own every active number, so no intermediate partial-index conflict
  -- can exist even when the student returns to a formerly occupied number.
  if v_source_found then
    update rakeezx.enrollments
      set status = 'transferred', end_date = nullif(p_source ->> 'end_date', '')::date,
          transfer_note = coalesce(p_source ->> 'transfer_note', ''),
          client_updated_at = v_source_stamp, device_id = p_source ->> 'device_id'
      where owner_id = v_owner and id = v_source_id
      returning * into v_source;
  else
    insert into rakeezx.enrollments (
      id, student_id, section_id, roll_no, start_date, end_date, status,
      transfer_note, client_updated_at, device_id
    ) values (
      v_source_id, v_student_id, v_source_section_id, nullif(p_source ->> 'roll_no', '')::integer,
      nullif(p_source ->> 'start_date', '')::date, nullif(p_source ->> 'end_date', '')::date,
      'transferred', coalesce(p_source ->> 'transfer_note', ''), v_source_stamp, p_source ->> 'device_id'
    ) returning * into v_source;
  end if;

  if v_destination_found then
    update rakeezx.enrollments
      set roll_no = null, start_date = nullif(p_destination ->> 'start_date', '')::date,
          end_date = null, status = 'active', client_updated_at = v_destination_stamp,
          device_id = p_destination ->> 'device_id'
      where owner_id = v_owner and id = v_destination_id
      returning * into v_destination;
  else
    insert into rakeezx.enrollments (
      id, student_id, section_id, roll_no, start_date, end_date, status,
      transfer_note, client_updated_at, device_id
    ) values (
      v_destination_id, v_student_id, v_destination_section_id, null,
      nullif(p_destination ->> 'start_date', '')::date, null, 'active',
      coalesce(p_destination ->> 'transfer_note', ''), v_destination_stamp, p_destination ->> 'device_id'
    ) returning * into v_destination;
  end if;

  select count(*) into v_source_plan_count from pg_catalog.jsonb_to_recordset(p_source_roster)
    as plan(id text, roll_no integer, client_updated_at bigint, device_id text);
  select count(*) into v_destination_plan_count from pg_catalog.jsonb_to_recordset(p_destination_roster)
    as plan(id text, roll_no integer, client_updated_at bigint, device_id text);
  select count(*) into v_source_active_count from rakeezx.enrollments
    where owner_id = v_owner and section_id = v_source_section_id and status = 'active' and deleted_at is null;
  select count(*) into v_destination_active_count from rakeezx.enrollments
    where owner_id = v_owner and section_id = v_destination_section_id and status = 'active' and deleted_at is null;

  if v_source_plan_count <> v_source_active_count or v_destination_plan_count <> v_destination_active_count then
    raise exception using errcode = 'P0001', message = 'Enrollment roster changed before transfer renumber';
  end if;
  if exists (
    select 1 from pg_catalog.jsonb_to_recordset(p_source_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
      left join rakeezx.enrollments enrollment on enrollment.owner_id = v_owner and enrollment.id = plan.id
      where enrollment.id is null or enrollment.section_id <> v_source_section_id or enrollment.status <> 'active' or
        enrollment.deleted_at is not null or coalesce(enrollment.client_updated_at, 0) > plan.client_updated_at
  ) or exists (
    select 1 from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
      left join rakeezx.enrollments enrollment on enrollment.owner_id = v_owner and enrollment.id = plan.id
      where enrollment.id is null or enrollment.section_id <> v_destination_section_id or enrollment.status <> 'active' or
        enrollment.deleted_at is not null or coalesce(enrollment.client_updated_at, 0) > plan.client_updated_at
  ) or exists (
    select 1 from (select id from pg_catalog.jsonb_to_recordset(p_source_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) ids group by id having count(*) > 1
  ) or exists (
    select 1 from (select id from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) ids group by id having count(*) > 1
  ) or exists (
    select 1 from (select roll_no from pg_catalog.jsonb_to_recordset(p_source_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) rolls group by roll_no having count(*) > 1
  ) or exists (
    select 1 from (select roll_no from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) rolls group by roll_no having count(*) > 1
  ) or not exists (
    select 1 from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
      where plan.id = v_destination_id and plan.roll_no = v_destination_roll
  ) then
    raise exception using errcode = 'P0001', message = 'Invalid or stale final enrollment roster';
  end if;

  -- The partial unique index ignores NULL.  Both rosters are clear only
  -- inside this transaction, then receive their complete final sequences.
  update rakeezx.enrollments set roll_no = null
    where owner_id = v_owner and section_id in (v_source_section_id, v_destination_section_id)
      and status = 'active' and deleted_at is null;

  update rakeezx.enrollments enrollment
    set roll_no = plan.roll_no, client_updated_at = plan.client_updated_at, device_id = plan.device_id
    from pg_catalog.jsonb_to_recordset(p_source_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
    where enrollment.owner_id = v_owner and enrollment.id = plan.id;
  update rakeezx.enrollments enrollment
    set roll_no = plan.roll_no, client_updated_at = plan.client_updated_at, device_id = plan.device_id
    from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
    where enrollment.owner_id = v_owner and enrollment.id = plan.id;

  select * into v_source from rakeezx.enrollments where owner_id = v_owner and id = v_source_id;
  select * into v_destination from rakeezx.enrollments where owner_id = v_owner and id = v_destination_id;
  return pg_catalog.jsonb_build_object(
    'source', pg_catalog.to_jsonb(v_source),
    'destination', pg_catalog.to_jsonb(v_destination),
    'source_roster', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment) order by enrollment.roll_no)
      from rakeezx.enrollments enrollment where owner_id = v_owner and section_id = v_source_section_id
        and status = 'active' and deleted_at is null), '[]'::jsonb),
    'destination_roster', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment) order by enrollment.roll_no)
      from rakeezx.enrollments enrollment where owner_id = v_owner and section_id = v_destination_section_id
        and status = 'active' and deleted_at is null), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.complete_account_profile(p_teacher_name text, p_phone text, p_teacher_form text, p_school_name text DEFAULT NULL::text, p_education_department text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_profile rakeezx.profile%rowtype; v_department text;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  perform rakeezx.lock_student_lifecycle(v_owner);
  select * into v_profile from rakeezx.profile where owner_id=v_owner for update;
  if not found then raise exception using errcode='42501',message='N117_PROFILE_CHECKPOINT_REQUIRED'; end if;
  if v_profile.provisioning_state in ('PROFILE_REQUIRED','PROVISIONING_REQUIRED','PROVISIONING') then
    v_department:=coalesce(p_education_department,v_profile.education_department);
    if v_department is null or not exists(select 1 from rakeezx.education_departments where name=v_department) then
      raise exception using errcode='22023',message='N117_DEPARTMENT_REQUIRED'; end if;
    if v_profile.provisioning_state='PROVISIONING' and v_profile.education_department is distinct from v_department then
      raise exception using errcode='22023',message='N117_INITIAL_DEPARTMENT_LOCKED'; end if;
    update rakeezx.profile set education_department=v_department where owner_id=v_owner;
  elsif p_education_department is not null and p_education_department is distinct from v_profile.education_department then
    raise exception using errcode='22023',message='N117_EXISTING_ACCOUNT_METADATA_ONLY';
  end if;
  perform rakeezx.complete_account_profile_before_n117(p_teacher_name,p_phone,p_teacher_form,p_school_name);
  return rakeezx.account_contract();
end $function$

CREATE OR REPLACE FUNCTION rakeezx.contribute_curriculum_sync_bootstrap(p_bootstrap_id text, p_device_id text, p_snapshot_hash text, p_units jsonb, p_lessons jsonb, p_authoritative boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid:=auth.uid(); v_state rakeezx.curriculum_sync_bootstraps%rowtype;
  v_conflicts jsonb:='[]'::jsonb; v_payload_hash text; v_existing boolean:=false;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_bootstrap_id,'')='' or char_length(p_bootstrap_id)>240 or
     coalesce(p_device_id,'')='' or char_length(p_device_id)>200 or
     p_snapshot_hash !~ '^[0-9a-f]{64}$' or jsonb_typeof(p_units)<>'array' or jsonb_typeof(p_lessons)<>'array' or
     jsonb_array_length(p_units)>5000 or jsonb_array_length(p_lessons)>20000 then
    raise exception using errcode='22023',message='Invalid curriculum bootstrap envelope';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':curriculum-bootstrap',0));
  select * into v_state from rakeezx.curriculum_sync_bootstraps where owner_id=v_owner for update;
  v_existing:=found;
  if v_existing and v_state.bootstrap_id<>p_bootstrap_id then
    raise exception using errcode='22023',message='Curriculum bootstrap identity mismatch';
  end if;
  if not v_existing and not p_authoritative then
    raise exception using errcode='22023',message='Authoritative curriculum bootstrap is required first';
  end if;
  if v_existing and v_state.state in ('CONFLICT','FAILED') then return rakeezx.curriculum_sync_bootstrap_result(v_owner); end if;
  v_payload_hash:=encode(sha256(convert_to(jsonb_build_object(
    'version',1,'units',p_units,'lessons',p_lessons)::text,'UTF8')),'hex');
  if v_existing and exists(select 1 from jsonb_array_elements(v_state.accepted_contributions) c
      where c->>'snapshotHash'=p_snapshot_hash) then
    if exists(select 1 from jsonb_array_elements(v_state.accepted_contributions) c
        where c->>'snapshotHash'=p_snapshot_hash and c->>'payloadHash'=v_payload_hash) then
      return rakeezx.curriculum_sync_bootstrap_result(v_owner);
    end if;
    raise exception using errcode='22023',message='Curriculum snapshot hash reused with different content';
  end if;

  if exists(select 1 from jsonb_array_elements(p_units) r where
      coalesce(r->>'id','')='' or coalesce(r->>'subject_id','')='' or
      (r->>'grade')::integer not between 1 and 12 or (r->>'term_index')::integer not between 1 and 6 or
      coalesce(r->>'name','')='' or (r->>'order')::integer<0 or (r->>'planned_sessions')::integer<0) or
     exists(select 1 from jsonb_array_elements(p_lessons) r where
      coalesce(r->>'id','')='' or coalesce(r->>'unit_id','')='' or coalesce(r->>'name','')='' or
      (r->>'order')::integer<0 or (r->>'planned_sessions')::integer<0) then
    raise exception using errcode='22023',message='Invalid curriculum bootstrap row';
  end if;
  if (select count(*) from jsonb_array_elements(p_units)) <>
       (select count(distinct r->>'id') from jsonb_array_elements(p_units) r) or
     (select count(*) from jsonb_array_elements(p_lessons)) <>
       (select count(distinct r->>'id') from jsonb_array_elements(p_lessons) r) then
    raise exception using errcode='22023',message='Duplicate curriculum bootstrap id';
  end if;

  if exists(select 1 from jsonb_array_elements(p_units) r where coalesce((r->>'deleted')::boolean,false)=false
      and not exists(select 1 from rakeezx.subjects s where s.owner_id=v_owner and s.id=r->>'subject_id' and s.deleted_at is null)) or
     exists(select 1 from jsonb_array_elements(p_lessons) r where coalesce((r->>'deleted')::boolean,false)=false
      and not exists(select 1 from jsonb_array_elements(p_units) u where u->>'id'=r->>'unit_id'
        and coalesce((u->>'deleted')::boolean,false)=false)
      and not exists(select 1 from rakeezx.units u where u.owner_id=v_owner and u.id=r->>'unit_id' and u.deleted_at is null)) then
    raise exception using errcode='23503',message='Invalid curriculum bootstrap reference';
  end if;

  select coalesce(jsonb_agg(x),'[]'::jsonb) into v_conflicts from (
    select jsonb_build_object('entity','units','id',u.id,'reason','same-id-different-content') x
      from rakeezx.units u join jsonb_array_elements(p_units) r on r->>'id'=u.id
      where u.owner_id=v_owner and rakeezx.curriculum_sync_normalize('units',to_jsonb(u))
        is distinct from rakeezx.curriculum_sync_normalize('units',r)
    union all
    select jsonb_build_object('entity','lessons','id',l.id,'reason','same-id-different-content')
      from rakeezx.lessons l join jsonb_array_elements(p_lessons) r on r->>'id'=l.id
      where l.owner_id=v_owner and rakeezx.curriculum_sync_normalize('lessons',to_jsonb(l))
        is distinct from rakeezx.curriculum_sync_normalize('lessons',r)
  ) conflicts;
  if jsonb_array_length(v_conflicts)>0 then
    if not v_existing then
      insert into rakeezx.curriculum_sync_bootstraps(owner_id,bootstrap_id,state,authoritative_source_device_id,conflict_evidence)
        values(v_owner,p_bootstrap_id,'CONFLICT',p_device_id,v_conflicts);
    else
      update rakeezx.curriculum_sync_bootstraps set state='CONFLICT',conflict_evidence=v_conflicts,
        updated_at=clock_timestamp() where owner_id=v_owner;
    end if;
    return rakeezx.curriculum_sync_bootstrap_result(v_owner);
  end if;

  insert into rakeezx.units(owner_id,id,subject_id,grade,term_index,name,"order",planned_sessions,
      client_updated_at,device_id,deleted_at)
    select v_owner,r->>'id',r->>'subject_id',(r->>'grade')::integer,(r->>'term_index')::integer,
      r->>'name',(r->>'order')::integer,(r->>'planned_sessions')::integer,
      nullif(r->>'client_updated_at','')::bigint,p_device_id,
      case when coalesce((r->>'deleted')::boolean,false) then clock_timestamp() end
    from jsonb_array_elements(p_units) r
    where not exists(select 1 from rakeezx.units u where u.owner_id=v_owner and u.id=r->>'id');
  insert into rakeezx.lessons(owner_id,id,unit_id,name,"order",planned_sessions,
      client_updated_at,device_id,deleted_at)
    select v_owner,r->>'id',r->>'unit_id',r->>'name',(r->>'order')::integer,
      (r->>'planned_sessions')::integer,nullif(r->>'client_updated_at','')::bigint,p_device_id,
      case when coalesce((r->>'deleted')::boolean,false) then clock_timestamp() end
    from jsonb_array_elements(p_lessons) r
    where not exists(select 1 from rakeezx.lessons l where l.owner_id=v_owner and l.id=r->>'id');

  if not v_existing then
    insert into rakeezx.curriculum_sync_bootstraps(owner_id,bootstrap_id,state,authoritative_source_device_id,
      accepted_contributions,unit_count,lesson_count)
    values(v_owner,p_bootstrap_id,'IN_PROGRESS',p_device_id,
      jsonb_build_array(jsonb_build_object('deviceId',p_device_id,'snapshotHash',p_snapshot_hash,'payloadHash',v_payload_hash)),
      (select count(*) from rakeezx.units where owner_id=v_owner),(select count(*) from rakeezx.lessons where owner_id=v_owner));
  else
    update rakeezx.curriculum_sync_bootstraps set
      accepted_contributions=accepted_contributions||jsonb_build_array(jsonb_build_object(
        'deviceId',p_device_id,'snapshotHash',p_snapshot_hash,'payloadHash',v_payload_hash)),
      unit_count=(select count(*) from rakeezx.units where owner_id=v_owner),
      lesson_count=(select count(*) from rakeezx.lessons where owner_id=v_owner),updated_at=clock_timestamp()
      where owner_id=v_owner;
  end if;
  return rakeezx.curriculum_sync_bootstrap_result(v_owner);
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.finalize_curriculum_sync_bootstrap(p_bootstrap_id text, p_device_id text, p_snapshot_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_state rakeezx.curriculum_sync_bootstraps%rowtype;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':curriculum-bootstrap',0));
  select * into v_state from rakeezx.curriculum_sync_bootstraps where owner_id=v_owner for update;
  if not found or v_state.bootstrap_id<>p_bootstrap_id then
    raise exception using errcode='22023',message='Curriculum bootstrap identity mismatch';
  end if;
  if v_state.state='COMPLETE' then return rakeezx.curriculum_sync_bootstrap_result(v_owner); end if;
  if v_state.state<>'IN_PROGRESS' or v_state.authoritative_source_device_id<>p_device_id or
     not exists(select 1 from jsonb_array_elements(v_state.accepted_contributions) c
       where c->>'deviceId'=p_device_id and c->>'snapshotHash'=p_snapshot_hash) then
    raise exception using errcode='22023',message='Curriculum bootstrap cannot be finalized';
  end if;
  update rakeezx.curriculum_sync_bootstraps set state='COMPLETE',updated_at=clock_timestamp(),
    completed_at=clock_timestamp(),conflict_evidence='[]'::jsonb where owner_id=v_owner;
  return rakeezx.curriculum_sync_bootstrap_result(v_owner);
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.plan_score_distribution(p_plan_id text, p_source text, p_targets text[], p_remove text[], p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_request jsonb; v_plan jsonb; v_fingerprint text; v_saved rakeezx.score_distribution_plans%rowtype;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_plan_id,'')='' or length(p_plan_id)>200 then raise exception using errcode='22023',message='Invalid plan identity'; end if;
  -- Short table locks prevent phantom inserts from racing plan validation. No
  -- unrelated owner rows are read, returned or mutated by the score operations.
  lock table rakeezx.items,rakeezx.score_subitems,rakeezx.score_subitem_completions,rakeezx.scores,
    rakeezx.teachings,rakeezx.sections,rakeezx.terms,rakeezx.years,rakeezx.subjects,rakeezx.students,
    rakeezx.enrollments,rakeezx.units,rakeezx.lessons,rakeezx.logs,rakeezx.attendance in share mode;
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':n73-plan:'||p_plan_id,0));
  if p_mode is null or p_mode not in ('definitions','preserve-target','automatic-safe') then
    raise exception using errcode='22023',message='Invalid distribution mode'; end if;
  v_request:=jsonb_build_object('source',p_source,'targets',p_targets,'remove',p_remove);
  if p_mode in ('preserve-target','automatic-safe') then v_request:=v_request||jsonb_build_object('mode',p_mode); end if;
  select * into v_saved from rakeezx.score_distribution_plans where owner_id=v_owner and id=p_plan_id;
  if found then
    if v_saved.request is distinct from v_request then raise exception using errcode='22023',message='Plan ID reused'; end if;
    return v_saved.plan;
  end if;
  v_plan:=rakeezx.n73_build_distribution(p_source,p_targets,p_remove,p_mode);
  v_fingerprint:=case when p_mode in ('preserve-target','automatic-safe') then md5(jsonb_build_object('state',rakeezx.n73_distribution_state(p_source,p_targets),
    'request',v_request,'operations',v_plan->'operations')::text) else md5(rakeezx.n73_distribution_state(p_source,p_targets)::text) end;
  v_plan:=(v_plan-'operations')||jsonb_build_object('planId',p_plan_id,'token',v_fingerprint,'expiresAt',clock_timestamp()+interval '15 minutes',
    'operations',v_plan->'operations');
  insert into rakeezx.score_distribution_plans(owner_id,id,request,fingerprint,plan) values(v_owner,p_plan_id,v_request,v_fingerprint,v_plan);
  return v_plan;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.provision_account_profile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid := auth.uid(); v_existed boolean;
begin
  if v_owner is null then raise exception using errcode='42501', message='Authentication required'; end if;
  select exists(select 1 from rakeezx.profile where owner_id=v_owner) into v_existed;
  perform rakeezx.provision_account_profile_before_provisioning_0297();
  if not v_existed then
    perform pg_catalog.set_config('rakeezx.account_provisioning_control','allow',true);
    update rakeezx.profile set provisioning_state='PROFILE_REQUIRED', provisioning_version=1
      where owner_id=v_owner and provisioning_state is null and profile_status='PENDING_PROFILE';
  end if;
  return rakeezx.account_contract();
end;
$function$

