      (select count(distinct value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'calendarDays')) <>
        pg_catalog.jsonb_array_length(p_defaults->'calendarDays') or
      (select count(distinct value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'timeProfiles')) <> 4 then
    raise exception using errcode='22023', message='Duplicate foundation identity';
  end if;

  insert into rakeezx.years(owner_id,id,label,hijri_start,hijri_end,"order",status)
    values(v_owner,v_year->>'id',v_year->>'label',(v_year->>'hijriStart')::int,
      (v_year->>'hijriEnd')::int,(v_year->>'order')::int,v_year->>'status')
    on conflict (owner_id,id) do nothing;
  insert into rakeezx.calendars(owner_id,id,year_id,source,label)
    values(v_owner,v_calendar->>'id',v_calendar->>'yearId','moe',v_calendar->>'label')
    on conflict (owner_id,id) do nothing;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'terms') loop
    insert into rakeezx.terms(owner_id,id,year_id,name,"index",start_date,end_date,status,calendar_id)
      values(v_owner,v_row->>'id',v_row->>'yearId',v_row->>'name',(v_row->>'index')::int,
        nullif(v_row->>'startDate','')::date,nullif(v_row->>'endDate','')::date,
        v_row->>'status',v_row->>'calendarId') on conflict (owner_id,id) do nothing;
  end loop;
  insert into rakeezx.subjects(owner_id,id,name,slug)
    values(v_owner,v_subject->>'id',v_subject->>'name',v_subject->>'slug')
    on conflict (owner_id,id) do nothing;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'calendarDays') loop
    insert into rakeezx.calendar_days(owner_id,id,calendar_id,date,kind,label)
      values(v_owner,v_row->>'id',v_row->>'calendarId',(v_row->>'date')::date,
        v_row->>'kind',v_row->>'label') on conflict (owner_id,id) do nothing;
  end loop;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'timeProfiles') loop
    insert into rakeezx.time_profiles(owner_id,id,name,"order",periods,overrides,active_from,active_to)
      values(v_owner,v_row->>'id',v_row->>'name',(v_row->>'order')::int,
        v_row->'periods',v_row->'overrides',nullif(v_row->>'activeFrom','')::date,
        nullif(v_row->>'activeTo','')::date) on conflict (owner_id,id) do nothing;
  end loop;
  update rakeezx.years set calendar_preset_id=v_preset where owner_id=v_owner and id=v_year->>'id' and calendar_preset_id is null;
  v_hash := pg_catalog.md5(p_defaults::text);
  v_manifest := pg_catalog.jsonb_build_object(
    'years',pg_catalog.jsonb_build_array(v_year->>'id'),
    'calendars',pg_catalog.jsonb_build_array(v_calendar->>'id'),
    'subjects',pg_catalog.jsonb_build_array(v_subject->>'id'),
    'terms',(select pg_catalog.jsonb_agg(value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'terms')),
    'calendarDays',(select pg_catalog.jsonb_agg(value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'calendarDays')),
    'timeProfiles',(select pg_catalog.jsonb_agg(value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'timeProfiles')));
  perform pg_catalog.set_config('rakeezx.account_provisioning_control','allow',true);
  update rakeezx.profile set provisioning_state='READY', provisioning_version=1,
      provisioning_hash=v_hash, provisioning_manifest=v_manifest,
      provisioning_completed_at=coalesce(provisioning_completed_at,now()) where owner_id=v_owner;
  if not rakeezx.account_provisioning_foundation_complete(v_owner) then
    raise exception using errcode='23514', message='Incomplete account foundation cannot be READY';
  end if;
  return pg_catalog.jsonb_build_object('contract',rakeezx.account_contract(),
    'snapshot',rakeezx.account_provisioning_snapshot());
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.rename_score_item(p_mutation_id text, p_device_id text, p_item_id text, p_revision bigint, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_item rakeezx.items%rowtype; v_saved rakeezx.score_domain_receipts%rowtype; v_envelope jsonb; v_result jsonb;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or length(p_mutation_id)>200 or coalesce(p_device_id,'')='' or length(p_device_id)>200 or
    length(btrim(p_name)) not between 1 and 50 or p_name is null then raise exception using errcode='22023',message='Invalid item name'; end if;
  v_envelope:=jsonb_build_object('deviceId',p_device_id,'itemId',p_item_id,'revision',p_revision,'name',p_name);
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':score-domain-receipt:'||p_mutation_id,0));
  select * into v_saved from rakeezx.score_domain_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_saved.request_envelope is distinct from v_envelope then raise exception using errcode='22023',message='Rename mutation ID reused'; end if;
    return v_saved.result;
  end if;
  select * into v_item from rakeezx.items where owner_id=v_owner and id=p_item_id and deleted_at is null for update;
  if not found or v_item.revision<>p_revision then raise exception using errcode='PT409',message='Item changed since review'; end if;
  perform set_config('rakeezx.score_domain_write','on',true);
  update rakeezx.items set name=btrim(p_name),device_id=p_device_id where owner_id=v_owner and id=p_item_id returning * into v_item;
  v_result:=jsonb_build_object('mutationId',p_mutation_id,'item',to_jsonb(v_item),'subitems','[]'::jsonb,'scores','[]'::jsonb);
  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result) values(v_owner,p_mutation_id,v_envelope,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.renumber_enrollment_roster(p_section_id text, p_roster jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_plan_count integer;
  v_remote_count integer;
begin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||':student-lifecycle-safety',0));
  if v_owner is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  if p_section_id is null or p_section_id = '' or pg_catalog.jsonb_typeof(p_roster) <> 'array' then
    raise exception using errcode = '22023', message = 'Invalid enrollment renumber payload';
  end if;

  -- Validate JSON before casting it through jsonb_to_recordset.  In
  -- particular, NULL would otherwise bypass a SQL NOT BETWEEN predicate.
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(p_roster) as entry(value)
      where pg_catalog.jsonb_typeof(entry.value) is distinct from 'object'
        or coalesce(entry.value ->> 'id', '') = ''
        or pg_catalog.jsonb_typeof(entry.value -> 'roll_no') is distinct from 'number'
        or not ((entry.value ->> 'roll_no') ~ '^[1-9][0-9]{0,2}$')
        or pg_catalog.jsonb_typeof(entry.value -> 'client_updated_at') is distinct from 'number'
  ) then
    raise exception using errcode = '22023', message = 'Invalid enrollment roster roll number or identity';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':section:' || p_section_id, 0));
  perform 1 from rakeezx.sections
    where owner_id = v_owner and id = p_section_id and deleted_at is null
    for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'Section is not active for current user';
  end if;
  perform 1 from rakeezx.enrollments
    where owner_id = v_owner and section_id = p_section_id
    for update;

  select count(*) into v_plan_count
    from pg_catalog.jsonb_to_recordset(p_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text);
  select count(*) into v_remote_count from rakeezx.enrollments
    where owner_id = v_owner and section_id = p_section_id and status = 'active' and deleted_at is null;
  if v_plan_count <> v_remote_count then
    raise exception using errcode = 'P0001', message = 'Enrollment roster changed before renumber';
  end if;
  if exists (
    select 1 from pg_catalog.jsonb_to_recordset(p_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
      left join rakeezx.enrollments enrollment
        on enrollment.owner_id = v_owner and enrollment.id = plan.id
      where plan.id is null or plan.roll_no is null or plan.roll_no not between 1 and 999 or plan.client_updated_at is null or
        enrollment.id is null or enrollment.section_id <> p_section_id or enrollment.status <> 'active' or
        enrollment.deleted_at is not null or coalesce(enrollment.client_updated_at, 0) > plan.client_updated_at
  ) or exists (
    select 1 from (
      select roll_no from pg_catalog.jsonb_to_recordset(p_roster)
        as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
    ) numbers group by roll_no having count(*) > 1
  ) or exists (
    select 1 from (
      select id from pg_catalog.jsonb_to_recordset(p_roster)
        as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
    ) ids group by id having count(*) > 1
  ) then
    raise exception using errcode = 'P0001', message = 'Invalid or stale enrollment roster plan';
  end if;

  -- NULL is valid and excluded by the partial unique index. It is visible only
  -- inside this transaction; the final intended sequence is assigned below.
  update rakeezx.enrollments
    set roll_no = null
    where owner_id = v_owner and section_id = p_section_id and status = 'active' and deleted_at is null;

  update rakeezx.enrollments enrollment
    set roll_no = plan.roll_no,
        client_updated_at = plan.client_updated_at,
        device_id = plan.device_id
    from pg_catalog.jsonb_to_recordset(p_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
    where enrollment.owner_id = v_owner and enrollment.id = plan.id;

  return (
    select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment)), '[]'::jsonb)
      from rakeezx.enrollments enrollment
      where enrollment.owner_id = v_owner and enrollment.section_id = p_section_id
        and enrollment.status = 'active' and enrollment.deleted_at is null
  );
end;
$function$
